def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (starts with +)
        if '+' in version:
            version_part, _ = version.split('+', 1)
        else:
            version_part = version

        # Split pre-release (starts with -)
        if '-' in version_part:
            base_part, prerelease_part = version_part.split('-', 1)
        else:
            base_part = version_part
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            pre_identifiers = []
            for ident in identifiers:
                if ident.isdigit():
                    pre_identifiers.append((0, int(ident)))  # numeric: (0, value)
                else:
                    pre_identifiers.append((1, ident))  # non-numeric: (1, string)
        else:
            pre_identifiers = None

        return (major, minor, patch, pre_identifiers)

    def compare_key(version):
        major, minor, patch, pre_identifiers = parse_version(version)

        # For sorting: versions without pre-release sort after those with
        # So we use (major, minor, patch, 1 if pre_identifiers is None else 0, pre_identifiers or [])
        if pre_identifiers is None:
            # No pre-release: sorts after pre-release versions
            return (major, minor, patch, 1, [])
        else:
            # Has pre-release: sorts before versions without
            return (major, minor, patch, 0, pre_identifiers)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=compare_key)

